let _menhir_print_token : token -> string =
  fun _tok ->
    match _tok with
    | AMPERAMPER ->
        "AMPERAMPER"
    | AMPERSAND ->
        "AMPERSAND"
    | AND ->
        "AND"
    | ANDOP _ ->
        "ANDOP"
    | AS ->
        "AS"
    | ASSERT ->
        "ASSERT"
    | BACKQUOTE ->
        "BACKQUOTE"
    | BANG ->
        "BANG"
    | BAR ->
        "BAR"
    | BARBAR ->
        "BARBAR"
    | BARRBRACKET ->
        "BARRBRACKET"
    | BEGIN ->
        "BEGIN"
    | CHAR _ ->
        "CHAR"
    | CLASS ->
        "CLASS"
    | COLON ->
        "COLON"
    | COLONCOLON ->
        "COLONCOLON"
    | COLONEQUAL ->
        "COLONEQUAL"
    | COLONGREATER ->
        "COLONGREATER"
    | COMMA ->
        "COMMA"
    | COMMENT _ ->
        "COMMENT"
    | CONSTRAINT ->
        "CONSTRAINT"
    | DO ->
        "DO"
    | DOCSTRING _ ->
        "DOCSTRING"
    | DONE ->
        "DONE"
    | DOT ->
        "DOT"
    | DOTDOT ->
        "DOTDOT"
    | DOTOP _ ->
        "DOTOP"
    | DOWNTO ->
        "DOWNTO"
    | ELSE ->
        "ELSE"
    | END ->
        "END"
    | EOF ->
        "EOF"
    | EOL ->
        "EOL"
    | EQUAL ->
        "EQUAL"
    | EXCEPTION ->
        "EXCEPTION"
    | EXTERNAL ->
        "EXTERNAL"
    | FALSE ->
        "FALSE"
    | FLOAT _ ->
        "FLOAT"
    | FOR ->
        "FOR"
    | FUN ->
        "FUN"
    | FUNCTION ->
        "FUNCTION"
    | FUNCTOR ->
        "FUNCTOR"
    | GREATER ->
        "GREATER"
    | GREATERRBRACE ->
        "GREATERRBRACE"
    | GREATERRBRACKET ->
        "GREATERRBRACKET"
    | HASH ->
        "HASH"
    | HASHOP _ ->
        "HASHOP"
    | IF ->
        "IF"
    | IN ->
        "IN"
    | INCLUDE ->
        "INCLUDE"
    | INFIXOP0 _ ->
        "INFIXOP0"
    | INFIXOP1 _ ->
        "INFIXOP1"
    | INFIXOP2 _ ->
        "INFIXOP2"
    | INFIXOP3 _ ->
        "INFIXOP3"
    | INFIXOP4 _ ->
        "INFIXOP4"
    | INHERIT ->
        "INHERIT"
    | INITIALIZER ->
